<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import { formatDateTime, statusLabel } from '../../utils/display'
import { dataSourceApi, type DataSourceView } from '../../api/platform'
import {
  flinkApi, integrationApi, realtimeApi,
  type FlinkEnvironment, type RealtimeCheckpointRow, type RealtimeExecution,
  type RealtimeJob, type RealtimeManagementRow, type RealtimePreCheckItem,
  type RealtimeSchemaChangeRow, type RealtimeTableOption, type RealtimeValidationRow
} from '../../api/domain'

const loading=ref(false), saving=ref(false), prechecking=ref(false), taskKeyword=ref('')
const rows=ref<RealtimeManagementRow[]>([]), sources=ref<DataSourceView[]>([]), envs=ref<FlinkEnvironment[]>([])
const editorVisible=ref(false), editorStep=ref(0), editing=ref<RealtimeJob|null>(null), advancedRuntime=ref(false)
const sourceDatabases=ref<Array<{name:string}>>([]), targetDatabases=ref<Array<{name:string}>>([])
const sourceTables=ref<RealtimeTableOption[]>([]), sourceTableKeyword=ref(''), selectedTables=ref<string[]>([])
const targetTables=reactive<Record<string,string>>({})
const precheckItems=ref<RealtimePreCheckItem[]>([]), yamlPreview=ref('')
const detailVisible=ref(false), detailLoading=ref(false), detailTab=ref('overview'), detailJob=ref<RealtimeJob|null>(null)
const detailRuntime=ref<any>(null), detailMetrics=ref<any>(null), detailLogs=ref<any>(null)
const checkpointRows=ref<RealtimeCheckpointRow[]>([])
const schemaChanges=ref<RealtimeSchemaChangeRow[]>([])
const validationRows=ref<RealtimeValidationRow[]>([])
const executionRows=ref<RealtimeExecution[]>([])
const validatingData=ref(false)
let detailTimer:ReturnType<typeof setInterval>|null=null

const form=reactive<any>({
  name:'', description:'', sourceDataSourceId:undefined, sourceDatabase:'', syncScope:'MULTI_TABLE',
  startupMode:'initial', timestampMillis:undefined, binlogFile:'', binlogPosition:0, gtid:'',
  syncSchema:true, addColumnPolicy:'AUTO', typeChangePolicy:'AUTO', renameColumnPolicy:'AUTO',
  dropColumnPolicy:'KEEP_TARGET', newTablePolicy:'AUTO', dropTablePolicy:'KEEP_TARGET', deletePolicy:'SYNC_DELETE', dataFilter:'',
  sinkDataSourceId:undefined, sinkDatabase:'ods', targetStrategy:'AUTO_CREATE', targetPrefix:'', targetSuffix:'', regexPattern:'', regexReplacement:'',
  bucketCount:0, replicationNum:1, runtimeEnvironmentId:undefined, parallelism:1,
  checkpointEnabled:true, checkpointIntervalSec:3, checkpointTimeoutSec:600, checkpointTolerance:3, externalizedCheckpoint:'RETAIN',
  restartStrategy:'FIXED_DELAY', restartAttempts:3, restartDelaySec:10, jmMemory:'1024m', tmMemory:'2048m', taskSlots:2,
  checkpointMinPauseSec:0, maxConcurrentCheckpoints:1, stateBackend:'rocksdb', checkpointStorage:'', savepointPath:'', advancedParams:''
})

const mysqlSources=computed(()=>sources.value.filter(s=>s.type==='MYSQL'))
const starrocksSources=computed(()=>sources.value.filter(s=>s.type==='STARROCKS'))
const filteredTables=computed(()=>{const q=sourceTableKeyword.value.trim().toLowerCase();return q?sourceTables.value.filter(t=>`${t.name} ${t.comment||''}`.toLowerCase().includes(q)):sourceTables.value})
const selectedTableOptions=computed(()=>selectedTables.value.map(name=>sourceTables.value.find(t=>t.name===name)).filter(Boolean) as RealtimeTableOption[])
const activeDetailRow=computed(()=>rows.value.find(r=>r.id===detailJob.value?.id))
const detailState=computed(()=>String(detailRuntime.value?.job?.observedState||detailJob.value?.observedState||'STOPPED').toUpperCase())
const detailRunning=computed(()=>['RUNNING','STARTING'].includes(detailState.value))
const filteredRows=computed(()=>{const q=taskKeyword.value.trim().toLowerCase();if(!q)return rows.value;return rows.value.filter(r=>[r.name,r.engineJobId,r.owner,r.sourceDatabase,r.sinkDatabase,r.environmentName].some(v=>String(v||'').toLowerCase().includes(q)))})

function scopeLabel(v?:string){return v==='SINGLE_TABLE'?'单表':v==='FULL_DATABASE'?'整库':'多表'}
function releaseLabel(v?:string){return statusLabel(v)}
function fmtCount(v?:number){return v==null?'—':new Intl.NumberFormat('zh-CN').format(v)}
function fmtBytes(v?:number){if(v==null)return '—';if(v>=1024**3)return `${(v/1024**3).toFixed(2)} GB`;if(v>=1024**2)return `${(v/1024**2).toFixed(1)} MB`;if(v>=1024)return `${(v/1024).toFixed(1)} KB`;return `${v} B`}
function fmtDuration(v?:number){if(v==null)return '—';if(v<1000)return `${v} ms`;if(v<60000)return `${(v/1000).toFixed(1)} s`;return `${(v/60000).toFixed(1)} min`}
function sourceName(id?:string|number){return sources.value.find(s=>String(s.id)===String(id))?.name||'未配置'}
function envName(id?:number){return envs.value.find(e=>e.id===id)?.name||'未配置'}
function jobIdShort(v?:string){return v?v.length>14?`${v.slice(0,12)}…`:v:'—'}
function cdcTone(t:RealtimeTableOption){return t.primaryKey?'ok':'warn'}
function startupLabel(v:string){return ({initial:'全量 + 增量','latest-offset':'仅增量',timestamp:'指定时间开始','specific-offset':'指定 Binlog 位点'} as any)[v]||v}
function deleteLabel(v:string){return ({SYNC_DELETE:'同步删除',IGNORE_DELETE:'忽略删除',LOGICAL_DELETE:'转换为逻辑删除'} as any)[v]||v}
function schemaChangeLabel(v:string){return ({ADD_COLUMN:'新增字段',ALTER_COLUMN_TYPE:'字段类型变化',RENAME_COLUMN:'字段重命名',DROP_COLUMN:'删除字段',ADD_TABLE:'新增表',DROP_TABLE:'删除表'} as any)[v]||v}
function schemaPolicyLabel(v:string){return ({AUTO:'自动同步',MANUAL:'人工确认',BLOCK:'阻塞任务',IGNORE:'忽略',KEEP_TARGET:'保留目标'} as any)[v]||v}
function schemaBehaviorLabel(v:string){return ({LENIENT:'自动同步兼容变更',EVOLVE:'自动同步',IGNORE:'忽略结构变化',EXCEPTION:'不兼容时阻塞'} as any)[v]||v}
function schemaBehavior(){if(!form.syncSchema)return 'IGNORE';if([form.typeChangePolicy,form.renameColumnPolicy].includes('BLOCK')||form.dropColumnPolicy==='BLOCK'||form.newTablePolicy==='BLOCK')return 'EXCEPTION';return 'LENIENT'}
function checkpointLabel(v?:string){const value=(v||'').toUpperCase();if(value==='COMPLETED')return '正常';if(value==='FAILED')return '失败';if(value==='IN_PROGRESS')return '进行中';if(value==='STOPPED'||value==='CANCELED'||value==='FINISHED')return '已停止';if(value==='UNKNOWN')return '状态未知';return '未采集'}
function lagLabel(v?:number){return v==null?'—':v<1000?`${v} ms`:`${(v/1000).toFixed(1)} s`}
function inactiveMetricText(){return detailState.value==='FAILED'?'任务失败':detailState.value==='UNKNOWN'?'状态未知':'已停止'}
function currentMetric(v:any,formatter?:(x:number)=>string){if(!detailRunning.value)return inactiveMetricText();if(v==null||Number.isNaN(Number(v)))return '未采集';return formatter?formatter(Number(v)):String(v)}

function buildSpec(){
  const specificOffset=form.gtid?.trim()?{gtid:form.gtid.trim()}:{file:form.binlogFile?.trim(),pos:Number(form.binlogPosition||0)}
  return {
    editorMode:'GUIDE',name:form.name,sourceDataSourceId:form.sourceDataSourceId,sinkDataSourceId:form.sinkDataSourceId,
    sourceDatabase:form.sourceDatabase,sinkDatabase:form.sinkDatabase,syncScope:form.syncScope,
    tables:selectedTables.value.map(t=>({sourceTable:t,targetTable:targetTables[t]||t})),
    startupMode:form.startupMode,timestampMillis:form.timestampMillis,specificOffset,
    schemaEvolution:schemaBehavior(),schemaPolicies:{syncSchema:form.syncSchema,addColumn:form.addColumnPolicy,typeChange:form.typeChangePolicy,renameColumn:form.renameColumnPolicy,dropColumn:form.dropColumnPolicy,newTable:form.newTablePolicy,dropTable:form.dropTablePolicy},
    deletePolicy:form.deletePolicy,dataFilter:form.dataFilter,
    targetStrategy:form.targetStrategy,targetNaming:{prefix:form.targetPrefix,suffix:form.targetSuffix,regexPattern:form.regexPattern,regexReplacement:form.regexReplacement},
    starrocks:{bucketCount:form.bucketCount,replicationNum:form.replicationNum},parallelism:form.parallelism,
    checkpoint:{enabled:form.checkpointEnabled,intervalSec:form.checkpointIntervalSec,timeoutSec:form.checkpointTimeoutSec,tolerableFailures:form.checkpointTolerance,externalized:form.externalizedCheckpoint,minPauseSec:form.checkpointMinPauseSec,maxConcurrent:form.maxConcurrentCheckpoints,storage:form.checkpointStorage},
    restart:{strategy:form.restartStrategy,attempts:form.restartAttempts,delaySec:form.restartDelaySec},
    resources:{jobManagerMemory:form.jmMemory,taskManagerMemory:form.tmMemory,taskSlots:form.taskSlots,stateBackend:form.stateBackend,savepointPath:form.savepointPath,advancedParams:form.advancedParams},
    chunkSize:8096,fetchSize:1024,heartbeatMs:30000,sink:{maxBytes:67108864,flushIntervalMs:2000}
  }
}
function payload(){return {name:form.name.trim(),description:form.description?.trim(),runtimeEnvironmentId:form.runtimeEnvironmentId,spec:buildSpec()}}

async function load(){loading.value=true;try{[rows.value,sources.value,envs.value]=await Promise.all([realtimeApi.management(),dataSourceApi.list(),flinkApi.list()])}catch(e){ElMessage.error(e instanceof Error?e.message:'实时任务加载失败')}finally{loading.value=false}}
function resetForm(){editing.value=null;editorStep.value=0;precheckItems.value=[];yamlPreview.value='';sourceTables.value=[];selectedTables.value=[];sourceTableKeyword.value='';for(const k of Object.keys(targetTables))delete targetTables[k];Object.assign(form,{name:'',description:'',sourceDataSourceId:mysqlSources.value[0]?.id,sourceDatabase:mysqlSources.value[0]?.databaseName||'',syncScope:'MULTI_TABLE',startupMode:'initial',timestampMillis:undefined,binlogFile:'',binlogPosition:0,gtid:'',syncSchema:true,addColumnPolicy:'AUTO',typeChangePolicy:'AUTO',renameColumnPolicy:'AUTO',dropColumnPolicy:'KEEP_TARGET',newTablePolicy:'AUTO',dropTablePolicy:'KEEP_TARGET',deletePolicy:'SYNC_DELETE',dataFilter:'',sinkDataSourceId:starrocksSources.value[0]?.id,sinkDatabase:starrocksSources.value[0]?.databaseName||'ods',targetStrategy:'AUTO_CREATE',targetPrefix:'',targetSuffix:'',regexPattern:'',regexReplacement:'',bucketCount:0,replicationNum:1,runtimeEnvironmentId:envs.value.find(e=>e.defaultEnvironment)?.id||envs.value.find(e=>e.enabled)?.id,parallelism:1,checkpointEnabled:true,checkpointIntervalSec:3,checkpointTimeoutSec:600,checkpointTolerance:3,externalizedCheckpoint:'RETAIN',restartStrategy:'FIXED_DELAY',restartAttempts:3,restartDelaySec:10,jmMemory:'1024m',tmMemory:'2048m',taskSlots:2,checkpointMinPauseSec:0,maxConcurrentCheckpoints:1,stateBackend:'rocksdb',checkpointStorage:'',savepointPath:'',advancedParams:''})}
async function openCreate(){resetForm();editorVisible.value=true;await Promise.all([loadSourceDatabases(),loadTargetDatabases()]);if(form.sourceDatabase)await loadSourceTables()}
async function openEdit(row:RealtimeManagementRow){resetForm();const job=await realtimeApi.get(row.id);editing.value=job;const s:any=job.spec||{};Object.assign(form,{name:job.name,description:job.description||'',runtimeEnvironmentId:job.runtimeEnvironmentId,sourceDataSourceId:s.sourceDataSourceId,sourceDatabase:s.sourceDatabase||'',syncScope:s.syncScope||((s.tables?.length||0)===1?'SINGLE_TABLE':'MULTI_TABLE'),startupMode:s.startupMode||'initial',timestampMillis:s.timestampMillis,binlogFile:s.specificOffset?.file||'',binlogPosition:s.specificOffset?.pos||0,gtid:s.specificOffset?.gtid||'',syncSchema:s.schemaPolicies?.syncSchema!==false,addColumnPolicy:s.schemaPolicies?.addColumn||'AUTO',typeChangePolicy:s.schemaPolicies?.typeChange||'AUTO',renameColumnPolicy:s.schemaPolicies?.renameColumn||'AUTO',dropColumnPolicy:s.schemaPolicies?.dropColumn||'KEEP_TARGET',newTablePolicy:s.schemaPolicies?.newTable||'AUTO',dropTablePolicy:s.schemaPolicies?.dropTable||'KEEP_TARGET',deletePolicy:s.deletePolicy||'SYNC_DELETE',dataFilter:s.dataFilter||'',sinkDataSourceId:s.sinkDataSourceId,sinkDatabase:s.sinkDatabase||'ods',targetStrategy:s.targetStrategy||'AUTO_CREATE',targetPrefix:s.targetNaming?.prefix||'',targetSuffix:s.targetNaming?.suffix||'',regexPattern:s.targetNaming?.regexPattern||'',regexReplacement:s.targetNaming?.regexReplacement||'',parallelism:s.parallelism||1,bucketCount:s.starrocks?.bucketCount||0,replicationNum:s.starrocks?.replicationNum||1,checkpointEnabled:s.checkpoint?.enabled!==false,checkpointIntervalSec:s.checkpoint?.intervalSec||3,checkpointTimeoutSec:s.checkpoint?.timeoutSec||600,checkpointTolerance:s.checkpoint?.tolerableFailures??3,externalizedCheckpoint:s.checkpoint?.externalized||'RETAIN',checkpointMinPauseSec:s.checkpoint?.minPauseSec??0,maxConcurrentCheckpoints:s.checkpoint?.maxConcurrent||1,checkpointStorage:s.checkpoint?.storage||'',restartStrategy:s.restart?.strategy||'FIXED_DELAY',restartAttempts:s.restart?.attempts||3,restartDelaySec:s.restart?.delaySec||10,jmMemory:s.resources?.jobManagerMemory||'1024m',tmMemory:s.resources?.taskManagerMemory||'2048m',taskSlots:s.resources?.taskSlots||2,stateBackend:s.resources?.stateBackend||'rocksdb',savepointPath:s.resources?.savepointPath||'',advancedParams:s.resources?.advancedParams||''});selectedTables.value=(s.tables||[]).map((t:any)=>t.sourceTable);for(const t of s.tables||[])targetTables[t.sourceTable]=t.targetTable||t.sourceTable;editorVisible.value=true;await Promise.all([loadSourceDatabases(),loadTargetDatabases()]);if(form.sourceDatabase)await loadSourceTables()}

async function loadSourceDatabases(){if(!form.sourceDataSourceId)return;try{sourceDatabases.value=await integrationApi.sourceDatabases(form.sourceDataSourceId)}catch(e){ElMessage.error(e instanceof Error?e.message:'读取源数据库失败')}}
async function loadTargetDatabases(){if(!form.sinkDataSourceId)return;try{targetDatabases.value=await integrationApi.targetDatabases(form.sinkDataSourceId)}catch(e){ElMessage.error(e instanceof Error?e.message:'读取目标数据库失败')}}
async function loadSourceTables(){if(!form.sourceDataSourceId||!form.sourceDatabase)return;try{sourceTables.value=await realtimeApi.tables(form.sourceDataSourceId,form.sourceDatabase);if(form.syncScope==='FULL_DATABASE'){selectedTables.value=sourceTables.value.map(t=>t.name);ensureTargetNames()}}catch(e){ElMessage.error(e instanceof Error?e.message:'读取表失败')}}
async function sourceChanged(){form.sourceDatabase='';selectedTables.value=[];sourceTables.value=[];await loadSourceDatabases()}
async function sourceDatabaseChanged(){selectedTables.value=[];for(const k of Object.keys(targetTables))delete targetTables[k];await loadSourceTables()}
async function sinkChanged(){form.sinkDatabase='';await loadTargetDatabases()}
function scopeChanged(){if(form.syncScope==='SINGLE_TABLE'&&selectedTables.value.length>1)selectedTables.value=selectedTables.value.slice(0,1);if(form.syncScope==='FULL_DATABASE')selectedTables.value=sourceTables.value.map(t=>t.name);ensureTargetNames()}
function toggleTable(name:string){if(form.syncScope==='FULL_DATABASE')return;if(form.syncScope==='SINGLE_TABLE')selectedTables.value=selectedTables.value.includes(name)?[]:[name];else selectedTables.value=selectedTables.value.includes(name)?selectedTables.value.filter(x=>x!==name):[...selectedTables.value,name];ensureTargetNames()}
function selectAllCdc(){if(form.syncScope==='SINGLE_TABLE')return;selectedTables.value=sourceTables.value.filter(t=>t.primaryKey).map(t=>t.name);ensureTargetNames()}
function ensureTargetNames(){for(const table of selectedTables.value){if(!targetTables[table])targetTables[table]=mappedName(table)}}
function mappedName(table:string){let name=table;if(form.regexPattern){try{name=name.replace(new RegExp(form.regexPattern,'g'),form.regexReplacement||'')}catch{}}return `${form.targetPrefix||''}${name}${form.targetSuffix||''}`}
function applyNaming(){for(const t of selectedTables.value)targetTables[t]=mappedName(t)}
function checkStep(step:number){if(step===0){if(!form.name.trim())return '请输入任务名称';if(!form.sourceDataSourceId)return '请选择 MySQL 数据源';if(!form.sourceDatabase)return '请选择源数据库';if(!form.sinkDataSourceId)return '请选择 StarRocks 数据源';if(!form.sinkDatabase)return '请选择目标数据库';if(!selectedTables.value.length)return '请选择至少一张同步表';const bad=selectedTableOptions.value.filter(t=>!t.primaryKey);if(bad.length)return `实时同步要求主键，以下表不可直接创建：${bad.map(t=>t.name).join('、')}`}if(step===2)ensureTargetNames();if(step===3&&!form.runtimeEnvironmentId)return '请选择 Flink 环境';return ''}
async function nextStep(){const m=checkStep(editorStep.value);if(m)return ElMessage.warning(m);if(editorStep.value<3){editorStep.value++;return}if(editorStep.value===3){editorStep.value=4;await runPrecheck()}}
function prevStep(){if(editorStep.value>0)editorStep.value--}
async function runPrecheck(){const m=[0,2,3].map(checkStep).find(Boolean);if(m)return ElMessage.warning(m);prechecking.value=true;try{const v=editing.value?await realtimeApi.validate(editing.value.id):await realtimeApi.previewValidate(payload());precheckItems.value=v.items||[];yamlPreview.value=v.yamlPreview||'';v.valid?ElMessage.success(v.message):ElMessage.warning(v.message)}catch(e){ElMessage.error(e instanceof Error?e.message:'创建前检查失败')}finally{prechecking.value=false}}
async function finalSave(){if(precheckItems.value.some(x=>x.blocking))return ElMessage.warning('存在阻断项，请修复后再创建');saving.value=true;try{if(editing.value)await realtimeApi.draft(editing.value.id,payload());else await realtimeApi.create(payload());ElMessage.success(editing.value?'实时任务配置已保存，可在列表中启动':'实时任务已创建，可在列表中启动');editorVisible.value=false;await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'保存实时任务失败')}finally{saving.value=false}}

async function start(row:RealtimeManagementRow){try{await ElMessageBox.confirm(`确认启动“${row.name}”？将向 Flink 提交 CDC 任务。`,'启动实时任务',{type:'warning',confirmButtonText:'启动',cancelButtonText:'取消'});await realtimeApi.start(row.id);ElMessage.success('实时任务已启动');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'启动失败')}}
async function stop(row:RealtimeManagementRow){try{await ElMessageBox.confirm(`确认停止“${row.name}”？`,'停止实时任务',{type:'warning',confirmButtonText:'停止',cancelButtonText:'取消'});await realtimeApi.stop(row.id);ElMessage.success('停止请求已完成');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'停止失败')}}
async function restart(row:RealtimeManagementRow){try{await ElMessageBox.confirm(`确认重启“${row.name}”？将停止当前 Flink Job 后重新提交。`,'重启实时任务',{type:'warning',confirmButtonText:'重启',cancelButtonText:'取消'});await realtimeApi.restart(row.id);ElMessage.success('实时任务已重启');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'重启失败')}}
async function copyTask(row:RealtimeManagementRow){try{const job=await realtimeApi.get(row.id);const base=`${job.name}-副本`;await realtimeApi.create({name:base,description:job.description||'',runtimeEnvironmentId:job.runtimeEnvironmentId,spec:{...(job.spec||{}),name:base}});ElMessage.success('任务已复制为新草稿，不会自动启动');await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'复制任务失败')}}
async function removeTask(row:RealtimeManagementRow){try{await ElMessageBox.confirm(`确认删除“${row.name}”？\n只删除平台任务定义和运行记录，不会删除 MySQL 或 StarRocks 中的业务数据。`,'删除实时任务',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消',confirmButtonClass:'el-button--danger'});await realtimeApi.remove(row.id);ElMessage.success('实时任务已删除');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'删除失败')}}

async function openDetail(row:RealtimeManagementRow,tab='overview'){detailVisible.value=true;detailTab.value=tab;detailLoading.value=true;detailMetrics.value=null;detailLogs.value=null;checkpointRows.value=[];schemaChanges.value=[];validationRows.value=[];executionRows.value=[];try{detailJob.value=await realtimeApi.get(row.id);await loadDetailRuntime();await Promise.all([loadDetailHistory(),loadDetailTab(tab)])}finally{detailLoading.value=false}startDetailPoll()}
async function loadDetailRuntime(){if(!detailJob.value)return;try{detailRuntime.value=await realtimeApi.runtime(detailJob.value.id)}catch{detailRuntime.value=null}if(!detailRunning.value)detailMetrics.value=null}
async function loadDetailHistory(){if(!detailJob.value)return;const id=detailJob.value.id;const all=await Promise.allSettled([realtimeApi.checkpointHistory(id),realtimeApi.schemaChanges(id),realtimeApi.validationResults(id),realtimeApi.executions(id)]);if(all[0].status==='fulfilled')checkpointRows.value=all[0].value;if(all[1].status==='fulfilled')schemaChanges.value=all[1].value;if(all[2].status==='fulfilled')validationRows.value=all[2].value;if(all[3].status==='fulfilled')executionRows.value=all[3].value}
async function loadDetailTab(tab:string){if(!detailJob.value)return;const id=detailJob.value.id;if(tab==='monitor'){if(!detailRunning.value){detailMetrics.value=null;return}try{detailMetrics.value=await realtimeApi.metrics(id)}catch{detailMetrics.value=null}}if(tab==='checkpoint'){if(detailRunning.value){try{await realtimeApi.checkpoints(id)}catch{}}try{checkpointRows.value=await realtimeApi.checkpointHistory(id)}catch{}}if(tab==='validation'){try{validationRows.value=await realtimeApi.validationResults(id)}catch{}}if(tab==='history'){try{executionRows.value=await realtimeApi.executions(id)}catch{}}if(tab==='logs'){try{detailLogs.value=await realtimeApi.logs(id)}catch(e){detailLogs.value=e instanceof Error?e.message:'暂时无法读取本地日志'}}}
function detailTabChanged(tab:any){void loadDetailTab(String(tab))}
function closeDetail(){stopDetailPoll();detailVisible.value=false}
function startDetailPoll(){stopDetailPoll();detailTimer=setInterval(async()=>{if(!detailVisible.value||!detailJob.value)return;await loadDetailRuntime();if(detailRunning.value&&detailTab.value==='monitor')await loadDetailTab('monitor');if(!detailRunning.value)detailMetrics.value=null},4000)}
function stopDetailPoll(){if(detailTimer){clearInterval(detailTimer);detailTimer=null}}
function metricValue(id:string){const arr=detailMetrics.value?.job;if(Array.isArray(arr)){const item=arr.find((x:any)=>x.id===id);if(item?.value!=null)return Number(item.value)}return undefined}
function vertexMetric(key:string){const vertices=detailMetrics.value?.vertices;if(!Array.isArray(vertices))return undefined;let sum=0,found=false;for(const v of vertices){const arr=v.metrics;if(!Array.isArray(arr))continue;const item=arr.find((x:any)=>x.id===key);if(item?.value!=null){sum+=Number(item.value);found=true}}return found?sum:undefined}
function taskManagerCount(){const t=detailMetrics.value?.taskmanagers?.taskmanagers;return Array.isArray(t)?t.length:undefined}
async function scanSchema(){if(!detailJob.value)return;try{schemaChanges.value=await realtimeApi.scanSchemaChanges(detailJob.value.id);ElMessage.success('表结构变更检测完成')}catch(e){ElMessage.error(e instanceof Error?e.message:'表结构检测失败')}}
async function runDataValidation(){if(!detailJob.value)return;validatingData.value=true;try{validationRows.value=await realtimeApi.dataValidation(detailJob.value.id);ElMessage.success('数据校验完成')}catch(e){ElMessage.error(e instanceof Error?e.message:'数据校验失败')}finally{validatingData.value=false}}
function validationTypeLabel(v:string){return ({ROW_COUNT:'行数对比',PRIMARY_KEY:'主键检查',PRIMARY_KEY_NULL:'主键空值',PRIMARY_KEY_DUPLICATE:'主键重复',TYPE_TIME_POLICY:'类型与时间策略',DELETE_POLICY:'DELETE 一致性策略'} as any)[v]||v}
function logText(){if(detailLogs.value==null)return '暂无本地执行日志';return typeof detailLogs.value==='string'?detailLogs.value:JSON.stringify(detailLogs.value,null,2)}

onMounted(load);onBeforeUnmount(stopDetailPoll)
</script>

<template>
<div class="ds-page ds-integration-page realtime-page">
  <PageHeader title="实时同步" subtitle="MySQL CDC → 独立 Flink CDC → StarRocks。创建体验面向数据开发，运行阶段面向生产运维。">
    <template #actions><el-button type="primary" @click="openCreate">+ 新建实时任务</el-button></template>
  </PageHeader>

  <div class="ds-card task-card">
    <div class="ds-toolbar"><strong>实时任务</strong><span class="count-tip">共 {{ filteredRows.length }} 个任务</span><div class="ds-spacer"/><el-input v-model="taskKeyword" clearable placeholder="搜索任务名称 / JobId / 负责人" style="width:340px"/><el-button @click="load" :loading="loading">刷新</el-button></div>
    <el-table :data="filteredRows" v-loading="loading" class="realtime-table" row-class-name="realtime-task-row" @row-click="(r:any)=>openDetail(r)">
      <el-table-column label="任务名称" min-width="190" show-overflow-tooltip><template #default="s"><button class="name-link" @click.stop="openDetail(s.row)">{{s.row.name}}</button><div class="minor">{{s.row.owner||'—'}} · {{scopeLabel(s.row.syncScope)}} {{s.row.tableCount}} 张表</div></template></el-table-column>
      <el-table-column label="来源" min-width="150" show-overflow-tooltip><template #default="s"><strong class="cell-main">{{sourceName(s.row.sourceDataSourceId)}}</strong><div class="minor">{{s.row.sourceDatabase||'—'}}</div></template></el-table-column>
      <el-table-column label="目标" min-width="150" show-overflow-tooltip><template #default="s"><strong class="cell-main">{{sourceName(s.row.sinkDataSourceId)}}</strong><div class="minor">{{s.row.sinkDatabase||'—'}}</div></template></el-table-column>
      <el-table-column label="发布状态" width="100"><template #default="s"><StatusBadge :status="s.row.releaseState" :label="releaseLabel(s.row.releaseState)"/></template></el-table-column>
      <el-table-column label="运行状态" width="100"><template #default="s"><StatusBadge :status="s.row.observedState"/></template></el-table-column>
      <el-table-column label="Flink 环境 / JobId" min-width="180" show-overflow-tooltip><template #default="s"><strong class="cell-main">{{s.row.environmentName||'未配置'}}</strong><div class="minor mono" :title="s.row.engineJobId">{{jobIdShort(s.row.engineJobId)}}</div></template></el-table-column>
      <el-table-column label="运行指标" min-width="150"><template #default="s"><div class="runtime-cell"><span>延迟：{{s.row.observedState==='RUNNING'?lagLabel(s.row.lagMs):'—'}}</span><span>Checkpoint：{{checkpointLabel(s.row.checkpointStatus)}}</span></div></template></el-table-column>
      <el-table-column label="最后更新时间" min-width="168"><template #default="s">{{formatDateTime(s.row.updatedAt)}}</template></el-table-column>
      <el-table-column label="操作" min-width="285" fixed="right"><template #default="s"><el-button link type="primary" @click.stop="openDetail(s.row)">详情</el-button><el-button v-if="s.row.observedState==='RUNNING'||s.row.observedState==='STARTING'" link type="warning" @click.stop="stop(s.row)">停止</el-button><el-button v-else link type="success" @click.stop="start(s.row)">启动</el-button><el-button v-if="s.row.observedState==='RUNNING'" link @click.stop="restart(s.row)">重启</el-button><el-button v-if="!['RUNNING','STARTING','STOPPING'].includes(s.row.observedState)" link @click.stop="openEdit(s.row)">编辑</el-button><el-button link @click.stop="openDetail(s.row,'logs')">日志</el-button><el-button link @click.stop="copyTask(s.row)">复制</el-button><el-button link type="danger" @click.stop="removeTask(s.row)">删除</el-button></template></el-table-column>
    </el-table>
  </div>

  <el-drawer v-model="editorVisible" size="60%" destroy-on-close :close-on-click-modal="false" class="wizard-drawer">
    <template #header><div class="drawer-head"><div><h3>{{editing?'编辑实时任务':'新建实时任务'}}</h3><p>业务配置由平台转换为 Flink CDC Pipeline，普通用户无需填写 Connector / Debezium 底层参数。</p></div></div></template>
    <div class="wizard-shell">
      <el-steps :active="editorStep" align-center finish-status="success" class="wizard-steps"><el-step title="选择数据"/><el-step title="同步配置"/><el-step title="目标配置"/><el-step title="运行配置"/><el-step title="确认创建"/></el-steps>

      <section v-if="editorStep===0" class="wizard-section">
        <div class="section-head"><div><h4>选择数据</h4><p>选择需要实时同步的 MySQL 数据库和表。底层 Connector、Server ID 等参数由平台自动生成。</p></div></div>
        <el-form label-position="top"><div class="form-grid"><el-form-item label="任务名称"><el-input v-model="form.name" placeholder="例如 用户订单实时同步"/></el-form-item><el-form-item label="任务描述"><el-input v-model="form.description" placeholder="可选"/></el-form-item></div></el-form>
        <div class="endpoint-pair">
          <div class="endpoint-card source-endpoint"><div class="endpoint-title"><strong>源端 MySQL</strong><span>实时读取 Binlog</span></div><el-form label-position="top"><el-form-item label="数据源"><el-select v-model="form.sourceDataSourceId" style="width:100%" @change="sourceChanged"><el-option v-for="s in mysqlSources" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="数据库"><el-select v-model="form.sourceDatabase" filterable style="width:100%" @change="sourceDatabaseChanged"><el-option v-for="d in sourceDatabases" :key="d.name" :label="d.name" :value="d.name"/></el-select></el-form-item></el-form></div>
          <div class="endpoint-arrow">→</div>
          <div class="endpoint-card target-endpoint"><div class="endpoint-title"><strong>目标 StarRocks</strong><span>写入实时明细数据</span></div><el-form label-position="top"><el-form-item label="数据源"><el-select v-model="form.sinkDataSourceId" style="width:100%" @change="sinkChanged"><el-option v-for="s in starrocksSources" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="数据库"><el-select v-model="form.sinkDatabase" filterable style="width:100%"><el-option v-for="d in targetDatabases" :key="d.name" :label="d.name" :value="d.name"/></el-select></el-form-item></el-form></div>
        </div>
        <el-form label-position="top" class="scope-form"><el-form-item label="同步范围"><el-radio-group v-model="form.syncScope" @change="scopeChanged"><el-radio-button value="SINGLE_TABLE">单表</el-radio-button><el-radio-button value="MULTI_TABLE">多表</el-radio-button><el-radio-button value="FULL_DATABASE">整库</el-radio-button></el-radio-group></el-form-item></el-form>
        <div class="table-picker"><div class="picker-head"><el-input v-model="sourceTableKeyword" clearable placeholder="搜索表名 / 注释" style="width:280px"/><div class="ds-spacer"/><el-button v-if="form.syncScope!=='SINGLE_TABLE'" @click="selectAllCdc">选择全部支持 CDC 的表</el-button><span>已选 {{selectedTables.length}} 张</span></div><div class="table-list"><button v-for="t in filteredTables" :key="t.name" type="button" :class="['table-option',{selected:selectedTables.includes(t.name),disabled:form.syncScope==='FULL_DATABASE'}]" @click="toggleTable(t.name)"><span :class="['check',{checked:selectedTables.includes(t.name)}]"><span v-if="selectedTables.includes(t.name)">✓</span></span><span class="table-copy"><strong>{{t.name}}</strong><small>{{t.comment||'暂无注释'}}</small></span><span class="pk">{{t.primaryKey?'PK':'无主键'}}</span><span class="rows">约 {{fmtCount(t.estimatedRows)}} 行</span><span :class="['cdc',cdcTone(t)]">{{t.cdcStatus}}</span></button></div></div>
      </section>

      <section v-else-if="editorStep===1" class="wizard-section">
        <div class="section-head"><div><h4>同步配置</h4><p>配置业务同步规则；TINYINT(1)、UNSIGNED、DATETIME/TIMESTAMP 等类型策略由平台自动处理。</p></div></div>
        <div class="form-card"><h5>启动模式</h5><el-radio-group v-model="form.startupMode"><el-radio value="initial">全量 + 增量</el-radio><el-radio value="latest-offset">仅增量</el-radio><el-radio value="timestamp">指定时间开始</el-radio><el-radio value="specific-offset">指定 Binlog 位点</el-radio></el-radio-group><div v-if="form.startupMode==='timestamp'" class="inline-config timestamp-config"><label>开始时间</label><el-date-picker v-model="form.timestampMillis" type="datetime" format="YYYY年MM月DD日 HH:mm:ss" value-format="x" placeholder="请选择开始消费时间"/><small>平台会转换为 Flink CDC 时间戳启动参数，并按源数据源时区处理。</small></div><div v-if="form.startupMode==='specific-offset'" class="form-grid inline-config"><el-input v-model="form.binlogFile" placeholder="Binlog File，例如 mysql-bin.000123"/><el-input-number v-model="form.binlogPosition" :min="0" style="width:100%"/><el-input v-model="form.gtid" placeholder="GTID（填写后优先使用 GTID）"/></div></div>
        <div class="form-card"><div class="card-head"><div><h5>表结构变更策略</h5><p>默认自动处理常见兼容变更；无需填写 Flink CDC 底层参数。</p></div><el-switch v-model="form.syncSchema" active-text="开启自动同步" inactive-text="关闭自动同步"/></div><div class="policy-grid" v-if="form.syncSchema"><label>新增字段<el-select v-model="form.addColumnPolicy"><el-option label="自动同步（默认）" value="AUTO"/><el-option label="阻塞任务" value="BLOCK"/><el-option label="忽略" value="IGNORE"/></el-select></label><label>字段类型变化<el-select v-model="form.typeChangePolicy"><el-option label="自动兼容（默认）" value="AUTO"/><el-option label="人工确认" value="MANUAL"/><el-option label="阻塞任务" value="BLOCK"/></el-select></label><label>字段重命名<el-select v-model="form.renameColumnPolicy"><el-option label="自动同步（默认）" value="AUTO"/><el-option label="人工确认" value="MANUAL"/><el-option label="阻塞任务" value="BLOCK"/></el-select></label><label>删除字段<el-select v-model="form.dropColumnPolicy"><el-option label="保留目标字段" value="KEEP_TARGET"/><el-option label="自动删除" value="AUTO"/><el-option label="阻塞任务" value="BLOCK"/></el-select></label><label>新增表<el-select v-model="form.newTablePolicy"><el-option label="自动同步（默认）" value="AUTO"/><el-option label="人工确认" value="MANUAL"/><el-option label="阻塞任务" value="BLOCK"/></el-select></label><label>删除表<el-select v-model="form.dropTablePolicy"><el-option label="保留目标表" value="KEEP_TARGET"/><el-option label="人工确认" value="MANUAL"/><el-option label="阻塞任务" value="BLOCK"/></el-select></label></div></div>
        <div class="form-card"><h5>数据过滤</h5><el-input v-model="form.dataFilter" placeholder="可选，例如 status = 1 AND created_at >= '2026-01-01'"/><div class="rule-note">过滤条件直接生成到 Flink CDC Transform。多表同步时请确保过滤字段在所有选中表中存在。</div></div>
        <div class="form-card"><h5>删除同步</h5><el-radio-group v-model="form.deletePolicy"><el-radio value="SYNC_DELETE">同步删除</el-radio><el-radio value="IGNORE_DELETE">忽略删除</el-radio><el-radio value="LOGICAL_DELETE">转换为逻辑删除</el-radio></el-radio-group><div class="rule-note">默认“同步删除”。源表无主键时平台会阻断创建，避免 UPDATE / DELETE 静默错误。</div></div>

      </section>

      <section v-else-if="editorStep===2" class="wizard-section">
        <div class="section-head"><div><h4>目标配置</h4><p>确认 StarRocks 建表策略，并完成源表与目标表映射。</p></div></div>
        <div class="target-summary"><span>目标位置</span><strong>{{sourceName(form.sinkDataSourceId)}} / {{form.sinkDatabase||'未选择'}}</strong></div><el-form label-position="top"><el-form-item label="目标表策略"><el-radio-group v-model="form.targetStrategy"><el-radio value="AUTO_CREATE">自动创建</el-radio><el-radio value="USE_EXISTING">使用已有表</el-radio><el-radio value="MANUAL">手动映射</el-radio></el-radio-group></el-form-item></el-form>
        <div class="form-card mapping-card"><div class="card-head"><div><h5>同步表与目标映射</h5><p>目标表默认同名，可按需修改；主键由平台自动识别。</p></div><div class="mapping-head-actions"><span>{{selectedTables.length}} 张已选</span><el-button @click="loadSourceTables">刷新表</el-button></div></div><div class="mapping-tools"><el-input v-model="form.targetPrefix" placeholder="目标表前缀，例如 ods_" @change="applyNaming"/><el-input v-model="form.targetSuffix" placeholder="目标表后缀" @change="applyNaming"/><el-input v-model="form.regexPattern" placeholder="正则匹配（可选）" @change="applyNaming"/><el-input v-model="form.regexReplacement" placeholder="正则替换" @change="applyNaming"/><el-button @click="applyNaming">应用规则</el-button></div><div class="mapping-board"><div class="mapping-source-pane"><div class="mapping-search"><el-input v-model="sourceTableKeyword" clearable placeholder="搜索表名或表备注"/></div><button v-for="table in selectedTableOptions.filter(t=>!sourceTableKeyword || `${t.name} ${t.comment||''}`.toLowerCase().includes(sourceTableKeyword.toLowerCase()))" :key="table.name" type="button" class="mapping-source-row"><span class="mapping-check">✓</span><span><strong>{{table.name}}</strong><small>{{table.comment||'TABLE'}}</small></span></button></div><div class="mapping-target-pane"><div class="mapping-pane-title"><strong>表映射与主键</strong><span>主键自动识别；目标表名可修改。</span></div><div class="mapping-target-list"><div v-for="table in selectedTableOptions" :key="table.name" class="mapping-target-item"><div class="mapping-item-title"><strong>{{table.name}}</strong><span v-if="table.primaryKey" class="pk-chip">🔑 主键已识别</span><span v-else class="pk-chip danger-chip">无主键</span></div><div class="mapping-input-row"><el-input :model-value="table.name" disabled/><span class="mapping-arrow">→</span><el-input v-model="targetTables[table.name]"/></div></div></div></div></div></div>
        <div class="form-card"><h5>StarRocks 建表</h5><div class="form-grid"><label class="field-label">Bucket 数量<el-input-number v-model="form.bucketCount" :min="0" style="width:100%"/><small>0 = 平台自动推导</small></label><label class="field-label">Replication<el-input-number v-model="form.replicationNum" :min="1" :max="3" style="width:100%"/></label></div></div>
      </section>

      <section v-else-if="editorStep===3" class="wizard-section">
        <div class="section-head"><div><h4>运行配置</h4><p>前 3 步只描述数据同步；这里才配置 Flink 运行参数。</p></div></div>
        <div class="form-card"><h5>基础配置</h5><div class="form-grid"><label class="field-label">Flink 环境<el-select v-model="form.runtimeEnvironmentId" style="width:100%"><el-option v-for="e in envs.filter(x=>x.enabled)" :key="e.id" :label="`${e.name} · Flink ${e.flinkVersion||'-'} / CDC ${e.flinkCdcVersion||'-'}`" :value="e.id"/></el-select></label><label class="field-label">并行度<el-input-number v-model="form.parallelism" :min="1" :max="128" style="width:100%"/></label><label class="field-label">Checkpoint 间隔（秒）<el-input-number v-model="form.checkpointIntervalSec" :min="1" style="width:100%"/></label><label class="field-label">失败重试次数<el-input-number v-model="form.restartAttempts" :min="0" :max="100" style="width:100%"/></label></div></div>
        <div class="checkpoint-card"><div><strong>Checkpoint</strong><span>实时 CDC 的故障恢复依赖 Checkpoint；生产任务建议保持启用。</span></div><el-switch v-model="form.checkpointEnabled" active-text="启用" inactive-text="关闭"/></div>
        <div class="checkpoint-grid" v-if="form.checkpointEnabled"><div><span>间隔</span><strong>{{form.checkpointIntervalSec}} 秒</strong></div><div><span>超时</span><strong>{{form.checkpointTimeoutSec}} 秒</strong></div><div><span>失败容忍</span><strong>{{form.checkpointTolerance}} 次</strong></div><div><span>外部化策略</span><strong>{{form.externalizedCheckpoint==='RETAIN'?'保留':'删除'}}</strong></div></div>
        <el-button link type="primary" @click="advancedRuntime=!advancedRuntime">{{advancedRuntime?'收起高级配置':'展开高级配置'}}</el-button>
        <div v-if="advancedRuntime" class="form-card advanced-card"><h5>高级配置</h5><div class="form-grid"><label class="field-label">JobManager 内存<el-input v-model="form.jmMemory"/></label><label class="field-label">TaskManager 内存<el-input v-model="form.tmMemory"/></label><label class="field-label">Task Slot 数量<el-input-number v-model="form.taskSlots" :min="1" style="width:100%"/></label><label class="field-label">失败重启策略<el-select v-model="form.restartStrategy" style="width:100%"><el-option label="固定延迟" value="FIXED_DELAY"/><el-option label="失败率" value="FAILURE_RATE"/><el-option label="不重启" value="NONE"/></el-select></label><label class="field-label">Checkpoint 超时（秒）<el-input-number v-model="form.checkpointTimeoutSec" :min="30" style="width:100%"/></label><label class="field-label">最小间隔（秒）<el-input-number v-model="form.checkpointMinPauseSec" :min="0" style="width:100%"/></label><label class="field-label">并发 Checkpoint<el-input-number v-model="form.maxConcurrentCheckpoints" :min="1" :max="4" style="width:100%"/></label><label class="field-label">State Backend<el-select v-model="form.stateBackend" style="width:100%"><el-option label="RocksDB" value="rocksdb"/><el-option label="HashMap" value="hashmap"/></el-select></label><label class="field-label">Checkpoint Storage<el-input v-model="form.checkpointStorage" placeholder="由 Flink 环境统一配置时可留空"/></label><label class="field-label">Savepoint<el-input v-model="form.savepointPath" placeholder="可选"/></label></div><label class="field-label">高级 Flink 参数<el-input v-model="form.advancedParams" type="textarea" :rows="4" placeholder="仅平台运维人员使用；普通任务请留空"/></label></div>
      </section>

      <section v-else class="wizard-section confirm-section">
        <div class="section-head"><div><h4>确认创建</h4><p>创建仅保存实时同步任务，不会自动启动；创建完成后请在任务列表单独点击“启动”。</p></div><el-button :loading="prechecking" @click="runPrecheck">重新检查</el-button></div>
        <div class="confirm-grid"><div><span>任务</span><strong>{{form.name}}</strong></div><div><span>同步链路</span><strong>{{sourceName(form.sourceDataSourceId)}} / {{form.sourceDatabase}} → {{sourceName(form.sinkDataSourceId)}} / {{form.sinkDatabase}}</strong></div><div><span>同步范围</span><strong>{{scopeLabel(form.syncScope)}} · {{selectedTables.length}} 张表</strong></div><div><span>启动模式</span><strong>{{startupLabel(form.startupMode)}}</strong></div><div><span>删除同步</span><strong>{{deleteLabel(form.deletePolicy)}}</strong></div><div><span>Flink</span><strong>{{envName(form.runtimeEnvironmentId)}} · 并行度 {{form.parallelism}}</strong></div></div>
        <div class="precheck-box"><div class="precheck-head"><strong>自动检查</strong><span>{{precheckItems.filter(x=>x.blocking).length}} 个阻断项，{{precheckItems.filter(x=>x.level==='WARNING').length}} 个提醒</span></div><div v-if="!precheckItems.length" class="empty-check">尚未获得检查结果</div><div v-for="item in precheckItems" :key="`${item.code}-${item.detail}`" :class="['check-row',item.level.toLowerCase()]"><span class="check-icon">{{item.blocking?'×':item.level==='WARNING'?'!':'✓'}}</span><strong>{{item.message}}</strong><span>{{item.detail}}</span></div></div>
        <details class="yaml-preview"><summary>查看平台生成的 Flink CDC Pipeline</summary><pre>{{yamlPreview||'预检后展示，密码会自动脱敏。'}}</pre></details>
      </section>
    </div>
    <template #footer><div class="wizard-footer"><el-button @click="editorVisible=false">取消</el-button><div class="ds-spacer"/><el-button v-if="editorStep>0" @click="prevStep">上一步</el-button><el-button v-if="editorStep<4" type="primary" @click="nextStep">下一步</el-button><el-button v-else type="primary" :loading="saving" @click="finalSave">{{editing?'保存修改':'创建'}}</el-button></div></template>
  </el-drawer>

  <el-drawer v-model="detailVisible" size="60%" destroy-on-close :show-close="false" class="detail-drawer" @closed="closeDetail">
    <template #header><div class="detail-head"><div><div class="eyebrow">实时同步任务</div><h3>{{detailJob?.name||'任务详情'}}</h3><p>{{sourceName((detailJob?.spec as any)?.sourceDataSourceId)}} / {{(detailJob?.spec as any)?.sourceDatabase}} → {{sourceName((detailJob?.spec as any)?.sinkDataSourceId)}} / {{(detailJob?.spec as any)?.sinkDatabase}}</p></div></div></template>
    <div v-loading="detailLoading" v-if="detailJob" class="detail-body">
      <div class="detail-summary"><div><span>运行状态</span><StatusBadge :status="detailRuntime?.job?.observedState||detailJob.observedState"/></div><div><span>更新时间</span><strong>{{formatDateTime(detailJob.updatedAt)}}</strong></div><div><span>Flink JobId</span><strong class="mono">{{detailRuntime?.execution?.engineJobId||'—'}}</strong></div><div><span>Flink 环境</span><strong>{{detailRuntime?.environment?.name||envName(detailJob.runtimeEnvironmentId)}}</strong></div><div><span>同步表</span><strong>{{(detailJob.spec as any)?.tables?.length||0}} 张</strong></div><div><span>负责人</span><strong>{{detailJob.createdBy}}</strong></div></div>
      <el-tabs v-model="detailTab" @tab-change="detailTabChanged" class="detail-tabs">
        <el-tab-pane label="概览" name="overview"><div v-if="!detailRunning" class="runtime-stopped-note"><StatusBadge :status="detailState"/><span>当前任务没有运行中的 Flink Job，以下实时指标不会沿用上一次运行的数据。</span></div><div class="overview-grid"><div class="metric-box"><span>源端输出速率（条/秒）</span><strong>{{currentMetric(vertexMetric('0.numRecordsOut'))}}</strong></div><div class="metric-box"><span>目标写入速率（条/秒）</span><strong>{{currentMetric(vertexMetric('0.numRecordsIn'))}}</strong></div><div class="metric-box"><span>当前延迟</span><strong>{{detailRunning?lagLabel(activeDetailRow?.lagMs):inactiveMetricText()}}</strong></div><div class="metric-box"><span>当前 Checkpoint</span><strong :class="{'metric-success':detailRunning&&checkpointLabel(activeDetailRow?.checkpointStatus)==='正常'}">{{detailRunning?checkpointLabel(activeDetailRow?.checkpointStatus):inactiveMetricText()}}</strong></div></div><div class="detail-card"><h4>任务信息</h4><el-descriptions :column="3" border><el-descriptions-item label="启动模式">{{startupLabel((detailJob.spec as any).startupMode||'initial')}}</el-descriptions-item><el-descriptions-item label="DELETE">{{deleteLabel((detailJob.spec as any).deletePolicy||'SYNC_DELETE')}}</el-descriptions-item><el-descriptions-item label="表结构变更">{{schemaBehaviorLabel((detailJob.spec as any).schemaEvolution||'EXCEPTION')}}</el-descriptions-item><el-descriptions-item label="创建时间">{{formatDateTime(detailJob.createdAt)}}</el-descriptions-item><el-descriptions-item label="更新时间">{{formatDateTime(detailJob.updatedAt)}}</el-descriptions-item><el-descriptions-item label="最近异常">{{detailJob.lastError||'无'}}</el-descriptions-item></el-descriptions></div></el-tab-pane>
        <el-tab-pane label="同步配置" name="config"><div class="detail-card"><h4>业务同步规则</h4><el-descriptions :column="3" border><el-descriptions-item label="来源">{{sourceName((detailJob.spec as any).sourceDataSourceId)}} / {{(detailJob.spec as any).sourceDatabase}}</el-descriptions-item><el-descriptions-item label="目标">{{sourceName((detailJob.spec as any).sinkDataSourceId)}} / {{(detailJob.spec as any).sinkDatabase}}</el-descriptions-item><el-descriptions-item label="同步范围">{{scopeLabel((detailJob.spec as any).syncScope)}}</el-descriptions-item><el-descriptions-item label="启动模式">{{startupLabel((detailJob.spec as any).startupMode||'initial')}}</el-descriptions-item><el-descriptions-item label="删除策略">{{deleteLabel((detailJob.spec as any).deletePolicy||'SYNC_DELETE')}}</el-descriptions-item><el-descriptions-item label="并行度">{{(detailJob.spec as any).parallelism||1}}</el-descriptions-item></el-descriptions><el-table :data="(detailJob.spec as any).tables||[]" size="small" class="detail-table"><el-table-column prop="sourceTable" label="源表"/><el-table-column prop="targetTable" label="目标表"/></el-table></div></el-tab-pane>
        <el-tab-pane label="运行监控" name="monitor"><div v-if="!detailRunning" class="runtime-stopped-note"><StatusBadge :status="detailState"/><span>任务已停止，当前没有 Source/Sink QPS、延迟、反压或运行时长。历史运行请查看“运行历史”。</span></div><div class="monitor-grid"><div class="metric-box"><span>源端输出速率（条/秒）</span><strong>{{currentMetric(vertexMetric('0.numRecordsOut'))}}</strong></div><div class="metric-box"><span>目标写入速率（条/秒）</span><strong>{{currentMetric(vertexMetric('0.numRecordsIn'))}}</strong></div><div class="metric-box"><span>反压时间（毫秒/秒）</span><strong>{{currentMetric(vertexMetric('0.backPressuredTimeMsPerSecond'))}}</strong></div><div class="metric-box"><span>运行时长</span><strong>{{currentMetric(metricValue('uptime'),fmtDuration)}}</strong></div><div class="metric-box"><span>Checkpoint 耗时</span><strong>{{currentMetric(metricValue('lastCheckpointDuration'),fmtDuration)}}</strong></div><div class="metric-box"><span>Checkpoint 失败次数</span><strong>{{currentMetric(metricValue('numberOfFailedCheckpoints'))}}</strong></div><div class="metric-box"><span>重启次数</span><strong>{{currentMetric(metricValue('numRestarts'))}}</strong></div><div class="metric-box"><span>TaskManager 数量</span><strong>{{currentMetric(taskManagerCount())}}</strong></div></div></el-tab-pane>
        <el-tab-pane label="Checkpoint" name="checkpoint"><div class="detail-card"><div class="card-head"><div><h4>Checkpoint 历史</h4><p>当前状态：{{detailRunning?checkpointLabel(activeDetailRow?.checkpointStatus):inactiveMetricText()}}。下表保留历史 Checkpoint，不代表当前任务仍在运行。</p></div><el-button @click="loadDetailTab('checkpoint')">刷新</el-button></div><el-table :data="checkpointRows" size="small"><el-table-column prop="checkpointId" label="Checkpoint ID"/><el-table-column label="状态"><template #default="s"><StatusBadge :status="s.row.status"/></template></el-table-column><el-table-column label="耗时"><template #default="s">{{fmtDuration(s.row.durationMs)}}</template></el-table-column><el-table-column label="State Size"><template #default="s">{{fmtBytes(s.row.stateSizeBytes)}}</template></el-table-column><el-table-column label="完成时间"><template #default="s">{{formatDateTime(s.row.completedAt)}}</template></el-table-column></el-table></div></el-tab-pane>
        <el-tab-pane label="日志" name="logs"><div class="detail-card"><div class="card-head"><div><h4>本地执行日志</h4><p>只展示当前最新一次执行在平台本地保存的提交/异常日志，不混入其他历史实例。</p></div><el-button @click="loadDetailTab('logs')">刷新</el-button></div><pre class="log-viewer">{{logText()}}</pre></div></el-tab-pane>
        <el-tab-pane label="表结构变更" name="schema"><div class="detail-card"><div class="card-head"><div><h4>表结构变更记录</h4><p>新增字段、兼容类型变化、字段重命名和新增表默认自动同步；破坏性变更按策略处理。</p></div><el-button @click="scanSchema">检测变更</el-button></div><div v-if="!schemaChanges.length" class="empty-panel">当前没有平台记录到的表结构变更。首次检测会建立基线快照，不会把现有字段误判为新增。</div><el-table v-else :data="schemaChanges" size="small"><el-table-column label="发生时间" min-width="170"><template #default="s">{{formatDateTime(s.row.occurredAt)}}</template></el-table-column><el-table-column prop="sourceTable" label="源表"/><el-table-column label="变更类型"><template #default="s">{{schemaChangeLabel(s.row.changeType)}}</template></el-table-column><el-table-column prop="ddlText" label="DDL" min-width="260" show-overflow-tooltip/><el-table-column label="平台处理"><template #default="s">{{schemaPolicyLabel(s.row.policyAction)}}</template></el-table-column><el-table-column prop="targetResult" label="目标结果"/><el-table-column label="状态"><template #default="s"><StatusBadge :status="s.row.status"/></template></el-table-column></el-table></div></el-tab-pane>
        <el-tab-pane label="数据校验" name="validation"><div class="detail-card"><div class="card-head"><div><h4>数据一致性校验</h4><p>Job Running 不等于数据一定正确。这里核对行数、主键、类型/时间策略和 DELETE 策略。</p></div><el-button type="primary" :loading="validatingData" @click="runDataValidation">执行校验</el-button></div><div v-if="!validationRows.length" class="empty-panel">尚未执行数据校验。</div><el-table v-else :data="validationRows" size="small"><el-table-column label="检查时间" min-width="170"><template #default="s">{{formatDateTime(s.row.checkedAt)}}</template></el-table-column><el-table-column label="校验项" min-width="150"><template #default="s">{{validationTypeLabel(s.row.validationType)}}</template></el-table-column><el-table-column prop="sourceTable" label="源表" min-width="130"/><el-table-column prop="sourceValue" label="源端" min-width="120"/><el-table-column prop="targetValue" label="目标端" min-width="120"/><el-table-column label="状态" width="100"><template #default="s"><StatusBadge :status="s.row.status"/></template></el-table-column><el-table-column prop="detail" label="说明" min-width="240" show-overflow-tooltip/></el-table></div></el-tab-pane>
        <el-tab-pane label="运行历史" name="history"><div class="detail-card"><div class="card-head"><div><h4>Flink Job 运行历史</h4><p>每次启动/重启都会形成独立执行实例，历史 JobId 与终态保留用于追溯。</p></div><el-button @click="loadDetailTab('history')">刷新</el-button></div><div v-if="!executionRows.length" class="empty-panel">暂无运行历史。</div><el-table v-else :data="executionRows" size="small"><el-table-column prop="definitionVersion" label="版本" width="80"><template #default="s">V{{s.row.definitionVersion}}</template></el-table-column><el-table-column prop="engineJobId" label="JobId" min-width="240" show-overflow-tooltip/><el-table-column label="状态" width="110"><template #default="s"><StatusBadge :status="s.row.status"/></template></el-table-column><el-table-column label="开始时间" min-width="170"><template #default="s">{{formatDateTime(s.row.startedAt||s.row.createdAt)}}</template></el-table-column><el-table-column label="结束时间" min-width="170"><template #default="s">{{formatDateTime(s.row.finishedAt)}}</template></el-table-column><el-table-column prop="errorMessage" label="异常" min-width="260" show-overflow-tooltip/></el-table></div></el-tab-pane>
      </el-tabs>
    </div>
  </el-drawer>
</div>
</template>

